 1	import { readFileSync } from "node:fs";
 2	import path from "node:path";
 3	import { PrismaClient } from "@prisma/client";
 4	
 5	const prisma = new PrismaClient();
 6	const MIGRATIONS_DIR = path.resolve(__dirname, "../prisma/migrations");
 7	
 8	export type Backfill = {
 9	  name: string;
10	  sqlFile: string;
11	  description: string;
12	};
13	
14	export const BACKFILLS: Backfill[] = [
15	  {
16	    name: "20240310121500_backfill_task_status",
17	    sqlFile: "20240310121500_backfill_task_status/migration.sql",
18	    description: "Set status='TODO' for legacy rows with NULL status.",
19	  },
20	];
21	
22	export function statements(sql: string): string[] {
23	  return sql
24	    .split(";")
25	    .map((s) => s.replace(/--[^\n]*/g, "").trim())
26	    .filter((s) => s.length > 0);
27	}
28	
29	export async function runBackfill(b: Backfill): Promise<number> {
30	  const sql = readFileSync(path.join(MIGRATIONS_DIR, b.sqlFile), "utf8");
31	  let affected = 0;
32	  await prisma.$transaction(async (tx) => {
33	    for (const stmt of statements(sql)) {
34	      affected += await tx.$executeRawUnsafe(stmt);
35	    }
36	  });
37	  return affected;
38	}
39	
40	async function main() {
41	  for (const b of BACKFILLS) {
42	    const rows = await runBackfill(b);
43	    console.log(`[backfill] ${b.name}: ${rows} row(s) updated`);
44	  }
45	}
46	
47	main()
48	  .catch((err) => {
49	    console.error(err);
50	    process.exitCode = 1;
51	  })
52	  .finally(() => prisma.$disconnect());

